with open(\"input.json\") as f:d=json.load(f)
def reach(s,t,removed):
 seen={s};todo=[s]
 while todo:
  v=todo.pop()
  if v==t:return True
  for e in d[\"edges\"]:
   if e[\"id\"] not in removed and e[\"source\"]==v and e[\"target\"] not in seen:
    seen.add(e[\"target\"]);todo.append(e[\"target\"])
 return False
rp=[];ap=[]
for p in d[\"probes\"]:
 if reach(p[\"source\"],p[\"target\"],set()):
  rp.append(p[\"id\"])
  if p[\"signed\"] is True and p[\"audience\"]==\"control\" and p[\"tenant\"]==p[\"resource_tenant\"] and d[\"now\"]<p[\"expires\"] and p[\"key\"] not in d[\"revoked_keys\"]:ap.append(p[\"id\"])
es=[e for e in d[\"edges\"] if e[\"removable\"]];best=None
for bits in itertools.product([False,True],repeat=len(es)):
 cut=[e for e,b in zip(es,bits) if b];ids=sorted(e[\"id\"] for e in cut);removed=set(ids)
 if any(reach(s,t,removed) for s,t in d[\"forbidden\"]):continue
 if not all(reach(s,t,removed) for s,t in d[\"required\"]):continue
 score=(sum(e[\"cost\"] for e in cut),len(ids),ids)
 if best is None or score<best:best=score
print(json.dumps(dict(reachable_probes=sorted(rp),authorized_probes=sorted(ap),repair_edges=best[2],repair_cost=best[0])))'"

